<?php

namespace MongoDB\BSON;

use JsonSerializable;
use MongoDB\Driver\Exception\InvalidArgumentException;
use Stringable;

/**
 * <div id="class.mongodb-bson-objectid" class="reference"> <h1 class="title">The MongoDB\BSON\ObjectId class</h1>  <div class="partintro"><p class="verinfo">(mongodb &gt;=1.0.0)</p>  <div class="section" id="mongodb-bson-objectid.intro">   <h2 class="title">简介</h2>   <p class="simpara">    BSON type for an    <a href="https://www.mongodb.com/docs/manual/reference/bson-types/#objectid" class="link external">»&nbsp;ObjectId</a>. The    value consists of 12 bytes, where the first four bytes are a timestamp    that reflect the ObjectId's creation. Specifically, the value consists of:   </p>   <ul class="itemizedlist">    <li class="listitem"><span class="simpara">a 4-byte value representing the seconds since the Unix epoch,</span></li>    <li class="listitem"><span class="simpara">a 5-byte random number unique to a machine and process, and</span></li>    <li class="listitem"><span class="simpara">a 3-byte counter, starting with a random value.</span></li>   </ul>   <p class="simpara">    In MongoDB, each document stored in a collection requires a unique    <span class="literal">_id</span> field that acts as a primary key. If an inserted    document omits the <span class="literal">_id</span> field, the extension automatically    generates an ObjectId for the <span class="literal">_id</span> field.   </p>   <p class="simpara">    Using ObjectIds for the <span class="literal">_id</span> field provides the following    additional benefits:   </p>   <ul class="itemizedlist">    <li class="listitem"><span class="simpara">The creation time of the ObjectId may be accessed using the <span class="methodname" style="color:#CC7832">{@link MongoDB\BSON\ObjectId::getTimestamp()}</span> method.</span></li>    <li class="listitem"><span class="simpara">Sorting on an <span class="literal">_id</span> field that stores ObjectId values is roughly equivalent to sorting by creation time.</span></li>   </ul>  </div>  <div class="section" id="mongodb-bson-objectid.synopsis">   <h2 class="title">类摘要</h2>   <div class="classsynopsis">    <span class="ooclass"><strong class="classname"></strong></span>    <div class="classsynopsisinfo">     <span class="modifier">final</span>     <span class="ooclass">      <span class="modifier">class</span> <strong class="classname">MongoDB\BSON\ObjectId</strong>     </span>     <span class="oointerface"><span class="modifier">implements</span>        <a href="https://php.net/manual/zh/class.mongodb-bson-objectidinterface.php" class="interfacename">MongoDB\BSON\ObjectIdInterface</a></span><span class="oointerface">,  <a href="https://php.net/manual/zh/class.mongodb-bson-type.php" class="interfacename">MongoDB\BSON\Type</a></span><span class="oointerface">,  <a href="https://php.net/manual/zh/class.jsonserializable.php" class="interfacename">JsonSerializable</a></span><span class="oointerface">,  <a href="https://php.net/manual/zh/class.stringable.php" class="interfacename">Stringable</a></span> {</div>    <div class="classsynopsisinfo classsynopsisinfo_comment">// 方法 </div>    <div class="methodsynopsis dc-description">   <span class="modifier">final</span> <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><a href="https://php.net/manual/zh/mongodb-bson-objectid.construct.php" class="methodname" style="color:#CC7832">__construct</a></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.null.php" class="type null" style="color:#EAB766">?</a></span><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span></span> <span class="parameter" style="color:#3A95FF">\$id</span><span class="initializer"> = <strong><span><a href="https://php.net/manual/zh/reserved.constants.php#constant.null">null</a></span></strong></span></span>)</div><div class="methodsynopsis dc-description"><span class="modifier">final</span> <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><a href="https://php.net/manual/zh/mongodb-bson-objectid.gettimestamp.php" class="methodname" style="color:#CC7832">getTimestamp</a></span>(): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.integer.php" class="type int" style="color:#EAB766">int</a></span></div><div class="methodsynopsis dc-description"><span class="modifier">final</span> <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><a href="https://php.net/manual/zh/mongodb-bson-objectid.jsonserialize.php" class="methodname" style="color:#CC7832">jsonSerialize</a></span>(): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.mixed.php" class="type mixed" style="color:#EAB766">mixed</a></span></div><div class="methodsynopsis dc-description"><span class="modifier">final</span> <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><a href="https://php.net/manual/zh/mongodb-bson-objectid.tostring.php" class="methodname" style="color:#CC7832">__toString</a></span>(): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span></div>   }</div>  </div>  <div class="section">   <h2 class="title">更新日志</h2>   <table class="doctable informaltable">         <thead>      <tr>       <th>版本</th>       <th>说明</th>      </tr>     </thead>     <tbody class="tbody">             <tr>        <td>PECL mongodb 2.0.0</td>        <td>         <span class="simpara">          此类不再实现 <span class="interfacename"><a href="https://php.net/manual/zh/class.serializable.php" class="interfacename">Serializable</a></span> 接口。         </span>        </td>       </tr>      <tr>       <td>PECL mongodb 1.12.0</td>       <td>        Implements <span class="interfacename"><a href="https://php.net/manual/zh/class.stringable.php" class="interfacename">Stringable</a></span> for PHP 8.0+.       </td>      </tr>      <tr>       <td>PECL mongodb 1.3.0</td>       <td>        <span class="simpara">         Renamed from <span class="literal">MongoDB\BSON\ObjectID</span> to         <span class="literal">MongoDB\BSON\ObjectId</span>.        </span>        <span class="simpara">         Implements <span class="interfacename"><a href="https://php.net/manual/zh/class.mongodb-bson-objectidinterface.php" class="interfacename">MongoDB\BSON\ObjectIdInterface</a></span>.        </span>       </td>      </tr>      <tr>       <td>PECL mongodb 1.2.0</td>       <td>        Implements <span class="interfacename"><a href="https://php.net/manual/zh/class.serializable.php" class="interfacename">Serializable</a></span> and        <span class="interfacename"><a href="https://php.net/manual/zh/class.jsonserializable.php" class="interfacename">JsonSerializable</a></span>.       </td>      </tr>     </tbody>       </table>  </div> </div> <h2>目录</h2><ul class="chunklist chunklist_reference"><li>{@link MongoDB\BSON\ObjectId::__construct} — Construct a new ObjectId</li><li>{@link MongoDB\BSON\ObjectId::getTimestamp} — Returns the timestamp component of this ObjectId</li><li>{@link MongoDB\BSON\ObjectId::jsonSerialize} — Returns a representation that can be converted to JSON</li><li>{@link MongoDB\BSON\ObjectId::__toString} — Returns the hexadecimal representation of this ObjectId</li></ul></div>
 * 
 * Class ObjectId
 * @link https://php.net/manual/zh/class.mongodb-bson-objectid.php
 */
final class ObjectId implements Type, ObjectIdInterface, JsonSerializable, Stringable
{
    /**
 * <div id="mongodb-bson-objectid.construct" class="refentry"> <div class="refnamediv">  <h1 class="refname">MongoDB\BSON\ObjectId::__construct</h1>  <p class="verinfo">(mongodb &gt;=1.0.0)</p><p class="refpurpose"><span class="refname">MongoDB\BSON\ObjectId::__construct</span> — <span class="dc-title">Construct a new ObjectId</span></p> </div> <div class="refsect1 description" id="refsect1-mongodb-bson-objectid.construct-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">final</span> <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>MongoDB\BSON\ObjectId::__construct</strong></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.null.php" class="type null" style="color:#EAB766">?</a></span><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span></span> <span class="parameter" style="color:#3A95FF">\$id</span><span class="initializer"> = <strong><span><a href="https://php.net/manual/zh/reserved.constants.php#constant.null">null</a></span></strong></span></span>)</div> </div> <div class="refsect1 parameters" id="refsect1-mongodb-bson-objectid.construct-parameters">  <h3 class="title">参数</h3>  <dl>       <dt><span class="parameter" style="color:#3A95FF">id</span> (<span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span>)</dt>    <dd>     <span class="simpara">      A 24-character hexadecimal string. If not provided, the extension will      generate an ObjectId.     </span>    </dd>     </dl> </div> <div class="refsect1 errors" id="refsect1-mongodb-bson-objectid.construct-errors">  <h3 class="title">错误／异常</h3>  <ul class="simplelist">   <li>Throws <span class="classname"><a href="https://php.net/manual/zh/class.mongodb-driver-exception-invalidargumentexception.php" class="classname">MongoDB\Driver\Exception\InvalidArgumentException</a></span> on argument parsing errors.</li>   <li>Throws <span class="classname"><a href="https://php.net/manual/zh/class.mongodb-driver-exception-invalidargumentexception.php" class="classname">MongoDB\Driver\Exception\InvalidArgumentException</a></span> if <span class="parameter" style="color:#3A95FF">id</span> is not a 24-character hexadecimal string.</li>  </ul> </div> <div class="refsect1 examples" id="refsect1-mongodb-bson-objectid.construct-examples">  <h3 class="title">示例</h3>  <div class="example" id="example-1">   <p><strong>示例 #1 <span class="function"><strong style="color:#CC7832">MongoDB\BSON\ObjectId::__construct()</strong></span> example</strong></p>   <div class="example-contents"><div class="phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br><br>var_dump</span><span style="color: #007700">(new </span><span style="color: #9876AA">MongoDB\BSON\ObjectId</span><span style="color: #007700">());<br><br></span><span style="color: #9876AA">var_dump</span><span style="color: #007700">(new </span><span style="color: #9876AA">MongoDB\BSON\ObjectId</span><span style="color: #007700">(</span><span style="color: #DD0000">'000000000000000000000001'</span><span style="color: #007700">));<br><br></span><span style="color: #9876AA">?&gt;</span></span></blockquote></div>   </div>   <div class="example-contents"><p>以上示例的输出类似于：</p></div>   <div class="example-contents screen" style="border-color:gray;background:#1E1F22;"><div class="examplescode"><blockquote style="border:1px gray solid;">object(MongoDB\BSON\ObjectId)#1&nbsp;(1)&nbsp;{<br>&nbsp;&nbsp;["oid"]=&gt;<br>&nbsp;&nbsp;string(24)&nbsp;"56732d3dda14d81214634921"<br>}<br>object(MongoDB\BSON\ObjectId)#1&nbsp;(1)&nbsp;{<br>&nbsp;&nbsp;["oid"]=&gt;<br>&nbsp;&nbsp;string(24)&nbsp;"000000000000000000000001"<br>}</blockquote></div>   </div>  </div> </div> <div class="refsect1 seealso" id="refsect1-mongodb-bson-objectid.construct-seealso">  <h3 class="title">参见</h3>  <ul class="simplelist">   <li><a href="https://www.mongodb.com/docs/manual/reference/bson-types/#objectid" class="link external">»&nbsp;ObjectId Reference</a></li>   <li><a href="https://www.mongodb.com/docs/manual/reference/bson-types/#objectid" class="link external">»&nbsp;BSON Types: ObjectId</a></li>  </ul> </div></div>
 * 
     * Construct a new ObjectId
     * @link https://php.net/manual/zh/mongodb-bson-objectid.construct.php
     * @param string|null $id A 24-character hexadecimal string. If not provided, the driver will generate an ObjectId.
     * @throws InvalidArgumentException if id is not a 24-character hexadecimal string.
     */
    final public function __construct(?string $id = null) {}

    /**
 * <div id="mongodb-bson-objectid.tostring" class="refentry"> <div class="refnamediv">  <h1 class="refname">MongoDB\BSON\ObjectId::__toString</h1>  <p class="verinfo">(mongodb &gt;=1.0.0)</p><p class="refpurpose"><span class="refname">MongoDB\BSON\ObjectId::__toString</span> — <span class="dc-title">Returns the hexadecimal representation of this ObjectId</span></p> </div> <div class="refsect1 description" id="refsect1-mongodb-bson-objectid.tostring-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">final</span> <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>MongoDB\BSON\ObjectId::__toString</strong></span>(): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span></div> </div> <div class="refsect1 parameters" id="refsect1-mongodb-bson-objectid.tostring-parameters">  <h3 class="title">参数</h3>  <p class="simpara">此函数没有参数。</p> </div> <div class="refsect1 returnvalues" id="refsect1-mongodb-bson-objectid.tostring-returnvalues">  <h3 class="title">返回值</h3>  <p class="simpara">   Returns the hexadecimal representation of this ObjectId.  </p> </div> <div class="refsect1 examples" id="refsect1-mongodb-bson-objectid.tostring-examples">  <h3 class="title">示例</h3>  <div class="example" id="example-1">   <p><strong>示例 #1 <span class="function"><strong style="color:#CC7832">MongoDB\BSON\ObjectId::__toString()</strong></span> example</strong></p>   <div class="example-contents"><div class="phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br><br>var_dump</span><span style="color: #007700">((string) new </span><span style="color: #9876AA">MongoDB\BSON\ObjectId</span><span style="color: #007700">());<br></span><span style="color: #9876AA">var_dump</span><span style="color: #007700">((string) new </span><span style="color: #9876AA">MongoDB\BSON\ObjectId</span><span style="color: #007700">(</span><span style="color: #DD0000">'000000000000000000000001'</span><span style="color: #007700">));<br><br></span><span style="color: #9876AA">?&gt;</span></span></blockquote></div>   </div>   <div class="example-contents"><p>以上示例的输出类似于：</p></div>   <div class="example-contents screen" style="border-color:gray;background:#1E1F22;"><div class="examplescode"><blockquote style="border:1px gray solid;">string(24)&nbsp;"56731b49da14d8747d701211"<br>string(24)&nbsp;"000000000000000000000001"</blockquote></div>   </div>  </div> </div> <div class="refsect1 seealso" id="refsect1-mongodb-bson-objectid.tostring-seealso">  <h3 class="title">参见</h3>  <ul class="simplelist">   <li><a href="https://www.mongodb.com/docs/manual/reference/bson-types/#objectid" class="link external">»&nbsp;ObjectId Reference</a></li>   <li><a href="https://www.mongodb.com/docs/manual/reference/bson-types/#objectid" class="link external">»&nbsp;BSON Types: ObjectId</a></li>  </ul> </div></div>
 * 
