     * @link https://php.net/manual/zh/mongodb-bson-objectid.tostring.php
     */
    final public function __toString(): string {}


    public static function __set_state(array $properties): self {}

    /**
 * <div id="mongodb-bson-objectid.gettimestamp" class="refentry"> <div class="refnamediv">  <h1 class="refname">MongoDB\BSON\ObjectId::getTimestamp</h1>  <p class="verinfo">(mongodb &gt;=1.2.0)</p><p class="refpurpose"><span class="refname">MongoDB\BSON\ObjectId::getTimestamp</span> — <span class="dc-title">Returns the timestamp component of this ObjectId</span></p> </div> <div class="refsect1 description" id="refsect1-mongodb-bson-objectid.gettimestamp-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">final</span> <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>MongoDB\BSON\ObjectId::getTimestamp</strong></span>(): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.integer.php" class="type int" style="color:#EAB766">int</a></span></div>  <p class="simpara">   The timestamp component of an ObjectId is its most significant 32 bits, which   denotes the number of seconds since the Unix epoch. This value is read as an   unsigned 32-bit integer with big-endian byte order.  </p>    <blockquote class="note" style="border:1px gray solid"><p><strong class="note" style="border:1px gray solid">注意</strong>:    <span class="simpara">    Because PHP's integer type is signed, some values returned by this    method may appear as negative integers on 32-bit platforms. The    <span class="literal">"%u"</span> formatter of <span class="function">{@link sprintf()}</span> may be    used to obtain a string representation of the unsigned decimal value.   </span>  </p></blockquote> </div> <div class="refsect1 parameters" id="refsect1-mongodb-bson-objectid.gettimestamp-parameters">  <h3 class="title">参数</h3>  <p class="simpara">此函数没有参数。</p> </div> <div class="refsect1 returnvalues" id="refsect1-mongodb-bson-objectid.gettimestamp-returnvalues">  <h3 class="title">返回值</h3>  <p class="simpara">   Returns the timestamp component of this ObjectId.  </p> </div> <div class="refsect1 errors" id="refsect1-mongodb-bson-objectid.gettimestamp-errors">  <h3 class="title">错误／异常</h3>  <ul class="simplelist">   <li>Throws <span class="classname"><a href="https://php.net/manual/zh/class.mongodb-driver-exception-invalidargumentexception.php" class="classname">MongoDB\Driver\Exception\InvalidArgumentException</a></span> on argument parsing errors.</li>  </ul> </div> <div class="refsect1 examples" id="refsect1-mongodb-bson-objectid.gettimestamp-examples">  <h3 class="title">示例</h3>  <div class="example" id="example-1">   <p><strong>示例 #1 <span class="function"><strong style="color:#CC7832">MongoDB\BSON\ObjectId::getTimestamp()</strong></span> example</strong></p>   <div class="example-contents"><div class="phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br><br>var_dump</span><span style="color: #007700">((new </span><span style="color: #9876AA">MongoDB\BSON\ObjectId</span><span style="color: #007700">())-&gt;</span><span style="color: #9876AA">getTimestamp</span><span style="color: #007700">());<br><br></span><span style="color: #9876AA">var_dump</span><span style="color: #007700">((new </span><span style="color: #9876AA">MongoDB\BSON\ObjectId</span><span style="color: #007700">(</span><span style="color: #DD0000">'0000002a0000000000000000'</span><span style="color: #007700">))-&gt;</span><span style="color: #9876AA">getTimestamp</span><span style="color: #007700">());<br><br></span><span style="color: #9876AA">?&gt;</span></span></blockquote></div>   </div>   <div class="example-contents"><p>以上示例的输出类似于：</p></div>   <div class="example-contents screen" style="border-color:gray;background:#1E1F22;"><div class="examplescode"><blockquote style="border:1px gray solid;">integer(1484854719)<br>integer(42)</blockquote></div>   </div>  </div> </div> <div class="refsect1 seealso" id="refsect1-mongodb-bson-objectid.gettimestamp-seealso">  <h3 class="title">参见</h3>  <ul class="simplelist">   <li><a href="https://www.mongodb.com/docs/manual/reference/bson-types/#objectid" class="link external">»&nbsp;ObjectId Reference</a></li>   <li><a href="https://www.mongodb.com/docs/manual/reference/bson-types/#objectid" class="link external">»&nbsp;BSON Types: ObjectId</a></li>  </ul> </div></div>
